<template>
  <div class="page-header q-mb-md">
    <div class="page">{{ header }}</div>
  </div>
  <q-form class="q-gutter-y-md rounded-borders q-pa-md bg-primary q-ma-md">
    <q-input
      ref="loginNameRef"
      filled
      v-model="loginForm.loginName"
      label="ชื่อล็อกอิน"
      :rules="[(val) => (val && val.length > 0) || 'ใส่ชื่อผู้ใช้',
        val => (val.length > 5 && val.length < 12) || 'ชื่อที่ใช้ลงทะเบียน ควรมีพยัญชนะ 6-12 ตัว']"
      color="white"
      autocomplete="username"
      ><template v-slot:prepend>
        <q-icon name="person_outline" />
      </template>
    </q-input>

    <q-input
      ref="passwordRef"
      filled
      v-model="loginForm.password"
      label="รหัสผ่าน"
      :type="isPwd ? 'password' : 'text'"
      :rules="[(val) => (val && val.length > 0) || 'ใส่รหัสผ่าน']"
      color="white"
      autocomplete="current-password"
    >
      <template v-slot:prepend>
        <q-icon name="lock_open" />
      </template>
      <template v-slot:append>
        <q-icon
          :name="isPwd ? 'visibility_off' : 'visibility'"
          class="cursor-pointer"
          @click="isPwd = !isPwd"
        /> </template
    ></q-input>
    <q-input
      ref="verificationRef"
      filled
      type="text"
      v-model="loginForm.captchaCode"
      label="รหัสยืนยัน"
      :rules="[
        (val) => (val && val.length > 3) || 'ใส่รหัสยืนยัน'
      ]"
      color="white"
    >
      <template v-slot:append>
        <img :src="verificationImg"  @click="getCode()" />
      </template>
      <template v-slot:prepend>
        <q-icon name="security" />
      </template>
    </q-input>

    <div class="row justify-between items-center">
      <router-link class="forget-pwd-tip" to="/forgot-password">
        ลืมรหัสผ่าน?
      </router-link>

      <q-btn
        @click.prevent="onSubmit"
        label="ล็อกอินตอนนี้"
        type="submit"
        color="brand"
      />
    </div>
  </q-form>
  <div class="txt-center">
    <router-link class="forget-pwd-tip" to="/register">
      ยังไม่ได้เข้าร่วม Jolly88? ลงทะเบียนตอนนี้
    </router-link>
  </div>
</template>

<script>
import { defineComponent, ref, reactive, onMounted } from "vue";
import { userStore } from "stores/index";
import { api } from "boot/axios";
import { useQuasar } from "quasar";
import { useRoute, useRouter } from "vue-router";

export default defineComponent({
  name: "LoginPage",
  setup() {
    const store = userStore();
    onMounted(() => {
      getCode();
    });
    const verificationImg = ref("");
    const loginForm = reactive({
      loginName: "",
      password: "",
      captchaCode: "",
      codeId: ""
    });
    const $q = useQuasar();
    const loginNameRef = ref();
    const passwordRef = ref();
    const verificationRef = ref();
    const router = useRouter();
    const route = useRoute();
    const getCode = () => {
      api
        .get("/member/verificationCode")
        .then((res) => {
          const response = res.data;
          if (response.code === 0) {
            verificationImg.value =
              "data:image/png;base64," + response.data.img;
            loginForm.codeId = response.data.id;
          }
        })
        .catch((e) => {
          $q.notify({
            color: "negative",
            position: "top",
            message: res.data.message,
            icon: "report_problem"
          });
        });
    };

    const onSubmit = () => {
      loginNameRef.value.validate();
      passwordRef.value.validate();
      verificationRef.value.validate();
      $q.loading.show({
        message: "การตรวจสอบการเข้าสู่ระบบ"
      });
      if (
        loginNameRef.value.hasError ||
        passwordRef.value.hasError ||
        verificationRef.value.hasError
      ) {
        $q.loading.hide();
      } else {
        store
          .memberLogin({
            loginName: loginForm.loginName,
            password: loginForm.password,
            captchaCode: loginForm.captchaCode,
            codeId: loginForm.codeId
          })
          .then(() => {
            $q.loading.hide();

            getCode();
            if (store.hasToken()) {
              const jumpUrl = route.query.redirect ? route.query.redirect : "/";
              router.go(jumpUrl);
            }
          })
          .catch((error) => {
            loginForm.captchaCode ="";
            $q.notify({
              color: "negative",
              position: "top",
              message: error.message,
              icon: "report_problem"
            });
            getCode();
          });
      }
    };
    return {
      header: "ล็อกอิน",
      loginNameRef,
      passwordRef,
      verificationRef,
      verificationImg,
      loginForm,
      onSubmit,
      store,
      isPwd: ref(true),
      getCode
    };
  }
});
</script>
<style lang="scss">
.page-header {
  background-image: linear-gradient(to right, #de4545, #db7e42);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  font-size: 28px;
  text-align: center;
  font-family: Wave;
  padding: 10px;
  display: flex;
  gap: 20px;
  align-content: center;
  justify-content: center;
}
