//   border-radius: 20px;

//   .q-field {
//     margin-left: 0;
//     border-radius: 20px;
//     margin-bottom: 15px;
//   }
// }
.verification {
  display: flex;
  padding: 10px;
}
.space-between {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.txt-center {
  text-align: center;
  padding: 0 10px;
}
</style>
